import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { getPosts } from '../utils/storage';
import ReactMarkdown from 'react-markdown';
import './styles/Home.scss';

function Home() {
  const [posts, setPosts] = useState([]);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [currentPage, setCurrentPage] = useState(1);
  const postsPerPage = 6;

  useEffect(() => {
    const stored = getPosts();
    const sorted = Array.isArray(stored)
      ? stored.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
      : [];
    setPosts(sorted);
  }, []);

  const categories = ['all', ...new Set(posts.map(p => p.category?.toLowerCase() || 'uncategorized'))];

  const filtered = posts.filter((post) => {
    const searchLower = search.toLowerCase();
    const matchesSearch =
      post.title.toLowerCase().includes(searchLower) ||
      post.content.toLowerCase().includes(searchLower) ||
      post.tags?.some(tag => tag.toLowerCase().includes(searchLower));

    const matchesCategory =
      selectedCategory === 'all' || post.category?.toLowerCase() === selectedCategory;

    return matchesSearch && matchesCategory;
  });

  const totalPages = Math.ceil(filtered.length / postsPerPage);
  const indexOfLast = currentPage * postsPerPage;
  const indexOfFirst = indexOfLast - postsPerPage;
  const currentPosts = filtered.slice(indexOfFirst, indexOfLast);

  return (
    <div className="home container">
      <h1 className="home__heading">Blog Feed</h1>

      <div className="home__filters">
        <input
          type="text"
          className="home__search"
          placeholder="Search posts..."
          value={search}
          onChange={(e) => {
            setSearch(e.target.value);
            setCurrentPage(1);
          }}
        />

        <select
          className="home__select"
          value={selectedCategory}
          onChange={(e) => {
            setSelectedCategory(e.target.value);
            setCurrentPage(1);
          }}
        >
          {categories.map((cat) => (
            <option key={cat} value={cat}>
              {cat.toUpperCase()}
            </option>
          ))}
        </select>
      </div>

      <div className="home__grid">
        {currentPosts.map((post) => (
          <div key={post.id} className="home__card">
            {post.image && (
              <img src={post.image} alt={post.title} className="home__card-image" />
            )}

            <div className="home__card-content">
              <Link to={`/post/${post.id}`}>
                <h3 className="home__card-title">{post.title}</h3>
              </Link>

              <ReactMarkdown>
                {post.content.substring(0, 120) + '...'}
              </ReactMarkdown>

              <div className="home__card-meta">
                <span className="home__card-category">{post.category}</span>
                {post.tags?.length > 0 && (
                  <span className="home__card-tags">
                    {post.tags.map((tag, i) => (
                      <span key={i} className="home__card-tag">#{tag}</span>
                    ))}
                  </span>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {totalPages > 1 && (
        <div className="home__pagination">
          {Array.from({ length: totalPages }, (_, i) => (
            <button
              key={i}
              className={`home__page-btn ${currentPage === i + 1 ? 'active' : ''}`}
              onClick={() => setCurrentPage(i + 1)}
            >
              {i + 1}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export default Home;
